def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    bg = background(g)
    frames = []
    for c in sorted(set(np.unique(g).tolist()) - {bg}):
        cells = list(zip(*np.where(g == c)))
        y0, x0, y1, x1 = bbox(cells)
        h, w = y1 - y0 + 1, x1 - x0 + 1
        s = max(h, w)
        if s % 2 == 0:
            s += 1
        found = None
        while found is None and s <= 2 * max(H, W) + 3:
            best = None
            for py in range(y1 - s + 1, y0 + 1):
                for px in range(x1 - s + 1, x0 + 1):
                    pat = np.zeros((s, s), bool)
                    seen = np.zeros((s, s), bool)
                    ok = True
                    ingrid = 0
                    for r in range(s):
                        for q in range(s):
                            if seen[r, q]:
                                continue
                            orb = {(r, q), (q, r), (s-1-r, q), (r, s-1-q), (s-1-r, s-1-q),
                                   (q, s-1-r), (s-1-q, r), (s-1-q, s-1-r)}
                            vals = set()
                            for a, b in orb:
                                seen[a, b] = True
                                yy, xx = py + a, px + b
                                if 0 <= yy < H and 0 <= xx < W:
                                    ingrid += 1
                                    v = g[yy, xx]
                                    if v == c:
                                        vals.add(1)
                                    elif v == bg:
                                        vals.add(0)
                            if len(vals) > 1:
                                ok = False
                                break
                            if vals == {1}:
                                for a, b in orb:
                                    pat[a, b] = True
                        if not ok:
                            break
                    if ok and (best is None or ingrid > best[0]):
                        best = (ingrid, pat)
            if best is not None:
                found = best[1]
            else:
                s += 2
        frames.append((s, c, found))
    S = max(f[0] for f in frames)
    out = np.full((S, S), bg, dtype=int)
    emit(out, f"Allocate a {S}x{S} canvas filled with background {bg}; the largest frame has size {S}.")
    for s, c, pat in sorted(frames, key=lambda f: -f[0]):
        o = (S - s) // 2
        sub = out[o:o+s, o:o+s]
        sub[pat] = c
        emit(out, f"Paint the completed symmetric frame of colour {c} (size {s}) centred on the canvas.")
    return out
